@CrossOrigin
@RestController
@RequestMapping("/APUQuery")
public class APUQueryRestController extends BaseSpringRestController {
	
	public APUQueryRestController( APUService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a APU using a UUID
     * @param		UUID aPUId
     * @return		APU
     */    
    @GetMapping("/load")
    public APU load( @RequestParam(required=true) UUID aPUId ) {
    	APU entity = null;

    	try {  
    		entity = service.getAPU( new APUFetchOneSummary( aPUId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load APU using Id " + aPUId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all APU business objects
     * @return		Set<APU>
     */
    @GetMapping("/")
    public List<APU> loadAll() {                
    	List<APU> aPUList = null;
        
    	try {
            // load the APU
            aPUList = service.getAllAPU();
            
            if ( aPUList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all APUs" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all APUs ", exc );
        	return null;
        }

        return aPUList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected APU aPU = null;
    protected APUService service = null;
    private static final Logger LOGGER = Logger.getLogger(APUQueryRestController.class.getName());
    
}
